# Generated by Descant: acceptance tests.

require "timekeeping_relay"

RSpec.describe TimekeepingRelay::IdempotencyKey do
  it "batches with the same positions but different entries or generations get different keys" do
    batch = lambda do |generation, entry_id|
      { "schema_version" => 1,
        "snapshots" => [{ "generation" => generation, "outbox_position" => 1,
                          "entry" => { "id" => entry_id, "company_id" => 1, "version" => 1 } }] }
    end
    uuid = /\A\h{8}-\h{4}-5\h{3}-[89ab]\h{3}-\h{12}\z/

    timekeeping_batch = described_class.for(batch.call(2, 10))
    monolith_batch = described_class.for(batch.call(2, 99))
    next_owner_batch = described_class.for(batch.call(3, 10))

    # "resends after an outage, and survives duplicates": a key shared by two different bodies would make the
    # consumer replay one batch's stored 200 for the other, and its rows would be marked sent without being applied.
    expect(timekeeping_batch).to match(uuid)
    expect([timekeeping_batch, monolith_batch, next_owner_batch].uniq.size).to eq(3)
    expect(described_class.for(batch.call(2, 10))).to eq(timekeeping_batch)
  end
end
